# Set Functions ----
## Speed/import ----
importDanio<-function(filename,num){
  withProgress(message="Loading your files",value=0,style="old",{
    d<-vector("list",num)   #initialize vector
    for(i in 1:num){
      sheets<-excel_sheets(filename[[i]])     #list of sheets in the file
      wells<-lapply(sheets,function(x) unlist(strsplit(x,"-"))[2])  #extract well name from sheet name
      plate<-read_excel(filename[[i]],sheet=1,range="B4")   
      plates<-gsub(" ","",colnames(plate)[1])                     #extract plate name from the Daniovision Export & remove spaces
      wellNames<-make.names(paste(plates,wells),unique=TRUE)         #assemble the well names from the extracted plate & well names
      imported<-lapply(sheets,
                       function(x) read_excel(filename[[i]],sheet=x,range = "I39:I45040", #pull the velocity range from the Daniovision export
                       col_names = FALSE))
      sorted<-lapply(imported,function(x) sort(x$...1,na.last=TRUE))  #sort the velocities, putting NA last
      names(sorted)<-wellNames
      d[[i]]<-sorted
      incProgress(1/num)
    }
  })
  Danio<-data.frame(list_flatten(d))
  colnames(Danio)<-names(list_flatten(d))
  Danio
}
importZantiks<-function(filename,num){
  withProgress(message="Loading your files",value=0,{
  z<-list()
  for(i in 1:num){
    imported<-read.csv(filename[i],header=TRUE)
    duration<-c(0,diff(x$RUNTIME))
    distance<-select(imported,starts_with("DISTANCE"))
    Speed<-na.omit(apply(distance,2,"/",MoreArgs=duration))
    colnames(Speed)<-gsub("DISTANCE_",colnames(Speed),replacement=paste0("Trial",i,"."))
    d[[i]]<-Speed
     incProgress(1/num)
    }
  })
  Zantiks<-data.frame(z)
  Zantiks
}
## Frequency ----
frequency<-function(Speed,bins,binNames){
  freq<-data.frame(matrix(ncol = ncol(Speed), nrow = 57))
  colnames(freq)<-colnames(Speed)
  withProgress(message="Processing...",value=0,{
    for (i in colnames(Speed)){
      f<-data.frame(table(cut(Speed[[i]],breaks=bins)))
      freq[[i]]<-as.numeric(f$Freq)
      incProgress(1/length(colnames(Speed)))
    }
    colnames(freq)<-colnames(Speed)
    rownames(freq)<-binNames
    freq
  })
}
## Percentage ----
percent<-function(frequency,binNames){
  perc<-data.frame(matrix(ncol=ncol(frequency),nrow=57))
  freqLength<-seq.int(1,ncol(frequency),1)
  withProgress(message="Processing...",value=0,{
    for (i in freqLength){
      s<-sum(frequency[[i]])
      perc[[i]]<-100*frequency[[i]]/s
      incProgress(1/freqLength)
    }
    colnames(perc)<-colnames(frequency)
    rownames(perc)<-binNames
    perc
  })
  
}
## Subset Data by Group ----
subDF<-function(data,key,group){
  f<-filter(key,Experimental.Group == group)
  groups<-unname(unlist(f[1]))
  data |> select(any_of(groups))
}
## Bootstrapping ----
CI<-function(df,ref,group,bounds){
  transposed<-t(subDF(df,ref,group))   #transpose the data frame to orient it for resampling
  bootstrapped<-resample::bootstrap(data=transposed,statistic=colMeans,R=10000) #resample the means for each sample 10,000 times
  confInt<-CI.percentile(x=bootstrapped,confidence=0.95)   #get the 95% confidence interval from the bootstrapping
  means<-unname(colMeans(transposed))     #extract the original means
  low<-unname(confInt[,1])                #extract the bounds from the bootstrapped CI
  high<-unname(confInt[,2])
  bounds<-data.frame(means,low,high)
  colnames(bounds)<-paste0(group,"_",Bounds)
  bounds        #assemble the means & bounds for the group into a table
}
bootGroups<-function(Groups,Data,Key,Bins,Bounds){
  #initialize the dataframe
  l<-seq(from=1,to=length(Groups),by=1)
  bootCI<-data.frame(matrix(ncol=(length(Groups)*3),nrow=nrow(Data)))
  #loop: obtain the bootstrap confidence intervals for each group
  for(i in l){
    p<-(i*3)-2
    sp<-seq(from=p,length.out=3)
    c<-CI(Data,Key,Groups[i],Bounds)
    bootCI[p]<-c[1]
    bootCI[p+1]<-c[2]
    bootCI[p+2]<-c[3]
  }
  bootCI<-cbind(Bin[1:nrow(bootCI)],bootCI) #add the bins as a column to the bootstrapped CI
  colnames(bootCI)<-c("Bin",paste0(rep(Groups,each=3),"_",Bounds)) #make meaningful column names
  bootCI
}
## Graphing ----
longForm<-function(Bin,Group,Boot){
  Bins<-as.numeric(Bin[1:nrow(Boot)])   #subset the bins to the length needed
  Y<-paste0(Group,"_Means")
  L<-paste0(Group,"_LowBound")
  U<-paste0(Group,"_HighBound")
  
  #make individual data frames for means & bounds, where column names are the statistic
  avg<-Boot |> select(any_of(Y))
  avg<- cbind(Bins,avg)
  colnames(avg)<-c("Bins",Group)
  
  low<-Boot |> select(any_of(L))
  low<- cbind(Bins,low)
  colnames(low)<-c("Bins",Group)
  
  up<-Boot |> select(any_of(U))
  up<- cbind(Bins,up)
  colnames(up)<-c("Bins",Group)
  #use the individual frames to make longform tables for graphing
  dataAvg <- avg %>% pivot_longer(cols=Group,names_to="Group",values_to="Mean")
  dataLow <- low %>% pivot_longer(cols=Group,names_to="Group",values_to="LowBound")
  dataUp <- up %>% pivot_longer(cols=Group,names_to="Group",values_to="HighBound")
  
  #merge the longform tables to make a final longform table with columns Bin, Group, Mean, LowBound, HighBound
  avgLowMerge<-merge(x=dataAvg,y=dataLow,by=c("Bins","Group"))
  longForm<-merge(x=avgLowMerge,y=dataUp,by=c("Bins","Group"))
  longForm
}  
