# Server ----
server <- function(input, output, session) {
  src="https://github.com/teasterbrooks/BehavioralAnalysis/blob/main/Behaviors_Logo.jpg"
  output$LabLogo<-renderText({c('<img src="',src,'>')})

# List of Uploaded Files ----
  imports<-reactive({
    switch(
      input$system,
      "Daniovision"=input$importDanio$datapath,
      "Zantiks"=input$importZantiks$datapath
    )
  })
  warn<-reactive({
    if(length(imports())==0){
      "Be patient after clicking Upload. Wait for this message to update before proceeding to the next tab. "
    }else{
      "You are ready to proceed!"
    }
  })
  output$warning<-renderText(warn())
  
  output$uploads<-renderPrint({
    imports()
  })  
# Run functions/Process data ----
  speed<-reactive({
    i<- switch(
      input$system,
      "Daniovision"=importDanio(imports(),length(imports())),
      "Zantiks"=importZantiks(imports(),length(imports()))
    )
    if(input$tidy==TRUE){
      i[,exd()]
    } else {
      i
    }
  })
  freq<-reactive({
    i<-frequency(speed(),lnBins,Bin)  
    if(input$tidy==TRUE){
      i[,exd()]
    } else {
      i
    }
    })
  perc<-reactive({
    i<-percent(freq(),Bin)
    if(input$tidy==TRUE){
      i[,exd()]
    } else {
      i
    }
  })
  
## Preview & Download Processed Data ----
  ### Preview
  output$preview.data<-renderDataTable({
  validate(
    need(imports(),"Upload your data to begin"),
    need(input$exportOutput,"Choose your output type")
  )
  switch(input$exportOutput,
  "Speed" = speed(),
  "Frequency" = freq(),
  "Percent" = perc()
  )
})

  ### Downloads
  output$Down<-downloadHandler(
    filename=paste(input$exportOutput,".csv",sep=""),
    content=function(file){
      write.csv(
        x=switch(input$exportOutput,
                 "Speed" = speed(),
                 "Frequency" = freq(),
                 "Percent" = perc()
        ),
        file=file)
    })
# Compute Stats
  
# Process Groups ----
  ## Create template for defining groups
    # Use uploaded files to make a list of all entries
    temp<-reactive({
    d<-data.frame(matrix(nrow = ncol(speed()), ncol = 1),row.names=colnames(speed()))
    colnames(d)<-c("Experimental.Group")
    d
  })
    # Download a .csv with all entries and space for adding group
    output$grpDown<-downloadHandler(
    filename="Groups.csv",
    content=function(file){
      write.csv(temp(),file)
    }
  )

  ## Import filled template  
  filled<-reactive({
    groupKey<-input$groupKey
    if (is.null(groupKey)) {
      return(NULL)
    }
    read.csv(groupKey$datapath,header=TRUE)
  })
  
  groupCheck<-reactive({
    req(filled())
    req(speed())
    a<-colnames(speed())
    b<-filled()[,1]
    x<-if(identical(a,b)==TRUE){
      "Your data matches your groupings!"
    } else {
      "Your groupings don't match your data. Please check your template!"
    }
  })
  
  output$checkGroup<-renderText(
      groupCheck()
  )

  # Make a list of all groups  
  g<-reactive({
    req(filled())
    as.list(unique(filled()[2]))
  })
  
  # Update options for users to select exclusions & normalize group  
  observe({updateSelectInput(session,"exclude",choices = g())})
  observe({updateSelectInput(session,"normTo",choices = h())})
  
  # Make a list of all non-excluded groups and set those as options for normalized output
  h<-reactive({
    n<-unname(unlist(g()))
    h<-n[!n %in% input$exclude]
    h
  })

  observe({updateSelectInput(session,"normBy",choices=h())})
  
  # Make a list of all non-excluded Wells
  exd<-reactive({
    req(filled())
    e<-unlist(input$exclude)
    f<-filter(filled(),Experimental.Group !=e)
    unname(unlist(f[1]))
  })

  # Normalize all wells to the control group
  norm<-reactive({
    req(filled())
    n<-unlist(input$normTo)
    c<-unname(unlist(filter(filled(),Experimental.Group == n)[1]))
    Norm<-unname(rowMeans(perc()[,c]))
    err<-ifelse(is.infinite(min(which(Norm==0))),ncol(perc()),min(which(Norm==0))-1)
    rws<-seq(1,err,by=1)
    p<-perc()[rws,]
    a<-apply(p,2,"/",MoreArgs=Norm[rws])
    df<-data.frame(unname(a))
    rownames(df)<-Bin[rws]
    colnames(df)<-colnames(perc())
    df
    })
  
  # Make a table of counts per group to confirm 
  defined<-reactive({
    req(filled())
    req(g())
    f<- filled() |> group_by(Experimental.Group)
    grouped<-data.frame(tally(f))
    grouped$p<-round(100*grouped$n/sum(grouped$n),digits=1)
    colnames(grouped)<-c("Group","Count","Percent")
    grouped
  })
  
  output$groupList<-renderTable(defined())
  
  # Make a data table of selected group's wells, normalized to control
  normFiltered<-reactive({
      req(norm())
      n<-as.character(input$normBy)
      subDF(norm(),filled(),n)
  })
  
  output$norms<-renderDataTable({
    validate(
      need(imports(),"Upload your data to begin"),
      need(input$groupKey,"Upload your group data to proceed"),
      need(input$normTo,"Choose your normalization group")
    )
    normFiltered()
    })
  
  normGroup<-reactive({
    as.character(input$normBy)
  })

  output$normsDown<-downloadHandler(
  filename=function(){
    paste(normGroup(),"_Normalized.csv",sep="")
  },
  content=function(file){
    write.csv(normFiltered(),file) 
  }
  )
# Make Matlab Graphs ----
  ## Bootstrapping ----
    norm.boot<-reactive({
      bootGroups(h(),norm(),filled(),Bin,Bounds)
  })

  perc.boot<-reactive({
    bootGroups(h(),perc(),filled(),Bin,Bounds)
    })
  
  ## Graphs ----
  observe({updateCheckboxGroupInput(session,"GraphGroups",choices = sort(h()))})
  colorScale<-reactive({
    if(length(input$lineCol)==0){
      viridisLite::viridis(length(input$GraphGroups))
    }else{
      input$lineCol
    }
      
  })
  yAxisLabel<-reactive({
    if(length(input$yLabel)==0){
      if(input$GraphType=="Logarithmic"){"Percent of Time (log)"}else{paste0("Percent of Time, Normalized to ",input$normTo)}
    }else{
      input$yLabel
    }
  })
  graphs<-eventReactive(input$graphGo,
    { req(input$GraphGroups)
      Graph<-switch(input$GraphType,
             "Logarithmic"=longForm(Bin,input$GraphGroups,perc.boot()),
             "Normalized"=longForm(Bin,input$GraphGroups,norm.boot()))
      ggplot(Graph, aes(x=Bins,y=Mean,color=Group,fill=Group)) +
      geom_line(size=2)+
      geom_ribbon(aes(ymin = LowBound, ymax = HighBound),alpha = 0.2)+
      theme(
        panel.border = element_rect(fill = "transparent", color = "black", linewidth = 2),
        panel.background = element_rect(fill="transparent"),
        axis.title.x = element_text(size = 16),
        axis.title.y = element_text(size = 16),
        axis.text = element_text(size=12)
      )+
      xlab(input$xLabel)+
      guides(color="legend")+
      scale_fill_manual(values=colorScale())+
      scale_color_manual(values=colorScale())+
      labs(
        title=input$graphTitle
      )+
      {if(input$GraphType=="Logarithmic")list(scale_y_log10(labels = label_log()),ylab("Percent of Time (log)"))}+
      {if(input$GraphType=="Normalized")list(ylab(paste0("Percent of Time, Normalized to ",input$normTo)))}      
  })

  output$boot.test<-renderPrint("Text")
  output$graph<-renderPlot({
  graphs()
  })
  graphExt<-reactive({
    paste0(input$GraphType,input$graphExt)
  })
  output$graphDown <- downloadHandler(
    filename = function(){graphExt()},
    content = function(file){
      ggsave(file,plot=graphs())
    })
  }
  
# App ----
shinyApp(ui = ui, server = server)
